/* (warehouse_id, destination_pincode, <carrier>) -> charge for each unique lane.
   carrier            : Delhivery (delhivery)
   representative wt  : 0.5 kg, Fwd (rate-card weight slabs applied; use
                        --weight to regenerate for another weight / RTO)
   source lanes       : C:\Users\Administrator\Documents\0909costAuto\bc_sales_export.csv (20,910 unique lanes served by Delhivery)
   charge == the web app engine's quote for this carrier on this lane.
   Self-contained BigQuery: run as-is, no python needed.
*/
WITH price_lookup AS (
  SELECT
    CAST(REGEXP_EXTRACT(v, r'^([0-9]+)\|') AS INT64) AS warehouse_id,
    CAST(REGEXP_EXTRACT(v, r'\|([0-9]+)\|') AS INT64) AS pincode,
    REGEXP_EXTRACT(v, r'\|([^|]+)\|([0-9.]+)$') AS carrier_zone,
    SAFE_CAST(REGEXP_EXTRACT(v, r'\|[^|]+\|([0-9.]+)$') AS FLOAT64) AS charge
  FROM UNNEST([
    '2|110003|C2|55.00',
    '2|110005|C2|55.00',
